package emitter

import (
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// generatedMarkers are the banners ANG writes at the top of generated files:
// the Go convention and the older one some templates (DTOs, Mongo) still use.
// Only files carrying one are ever removed automatically; a hand-written file
// at the same path stays.
var generatedMarkers = []string{"Code generated by ANG", "AUTO-GENERATED by ANG", "Generated by ANG. Do not edit."}

// RemoveGeneratedOutput deletes the ANG-generated files at the given paths
// (relative to the output directory; a path may be a file or a directory) and
// the directories that become empty. It is how a step the project no longer
// uses takes its previous output with it.
func (e *Emitter) RemoveGeneratedOutput(paths ...string) error {
	return removeGeneratedUnder(e.OutputDir, paths...)
}

// removeGeneratedUnder is RemoveGeneratedOutput for paths relative to base.
func removeGeneratedUnder(base string, paths ...string) error {
	for _, rel := range paths {
		root := filepath.Join(base, filepath.FromSlash(rel))
		info, err := os.Stat(root)
		if os.IsNotExist(err) {
			continue
		}
		if err != nil {
			return err
		}
		if !info.IsDir() {
			if err := removeIfGenerated(root); err != nil {
				return err
			}
			continue
		}
		var dirs []string
		err = filepath.WalkDir(root, func(path string, d fs.DirEntry, walkErr error) error {
			if walkErr != nil {
				return walkErr
			}
			if d.IsDir() {
				dirs = append(dirs, path)
				return nil
			}
			return removeIfGenerated(path)
		})
		if err != nil {
			return err
		}
		// Deepest first, so a parent is only removed once its children are.
		sort.Slice(dirs, func(i, j int) bool { return len(dirs[i]) > len(dirs[j]) })
		for _, dir := range dirs {
			entries, err := os.ReadDir(dir)
			if err == nil && len(entries) == 0 {
				_ = os.Remove(dir)
			}
		}
	}
	return nil
}

func removeIfGenerated(path string) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	head := string(data)
	if len(head) > 512 {
		head = head[:512]
	}
	generated := false
	for _, marker := range generatedMarkers {
		if strings.Contains(head, marker) {
			generated = true
			break
		}
	}
	if !generated {
		return nil
	}
	if err := os.Remove(path); err != nil && !os.IsNotExist(err) {
		return err
	}
	logGenerated("Removed unused generated file: %s\n", path)
	return nil
}
